window = 3
series_x = Series([1.0, 2.0, 1e12, 1e7, 6.0, 5.0, 8.0, 7.0])
series_y = Series([2.0, 1.0, 3.0, -1e12, 4.0, 7.0, 6.0, 9.0])

for method in ['cov', 'corr']:
    try:
        result = getattr(series_x.rolling(window), method)(series_y)
