        probe_exception("window=3; series_x = Series([1.0,2.0,1e12,1e7,6.0,5.0,8.0,7.0]); series_y = Series([2.0,1.0,3.0,-1e12,4.0,7.0,6.0,9.0]); getattr(series_x.rolling(3), method)(series_y) for method in cov/corr; assert not result.iloc[window-1:].isna().any()", e)

